USE health_ai_platform;

-- ============================================================
-- Real policy content for the 5 core Member Services
-- knowledge_docs (v1/v2/v3 of each = 15 rows total), replacing
-- the Faker gibberish generated by generate_seed_data.py.
-- ============================================================

-- --- ID Card Reissue SOP -----------------------------
UPDATE knowledge_docs SET content = 'Members may request a replacement ID card through the member portal, by phone, or by mail request. Standard reissue ships within 7-10 business days at no charge. A member may request up to 3 replacement cards per calendar year at no charge; a 4th or subsequent request in the same year incurs a small processing fee unless the member reports the prior card as lost due to theft, in which case the fee is waived with a brief explanation noted on the ticket. Expedited (2-3 business day) shipping is available for an additional fee. Digital ID cards are available immediately through the member portal or mobile app regardless of physical card request status, and are always free.'
WHERE dept_id = 10 AND title = 'ID Card Reissue SOP';

UPDATE knowledge_docs SET content = 'Revision 2 adds a name/address verification step before mailing a physical card: if the mailing address on the request differs from the address on file, the request is held pending an Address Change Verification (per that policy) rather than shipping to an unverified address, since ID card requests to a new address were identified as a common fraud vector. This revision also reduces the free-replacement limit in v1 from 3 to 2 per calendar year, with the fee threshold and theft-waiver exception otherwise unchanged.'
WHERE dept_id = 10 AND title = 'ID Card Reissue SOP v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a dependent-card handling clause: a request for a dependent''s replacement card must come from the subscriber (primary member) or the dependent themselves if they are 18 or older, not from any other caller claiming to act on the dependent''s behalf, even a family member. This revision also formalizes the digital ID card in v1 as the default recommendation offered to every caller before a physical card is processed, since a meaningful share of physical requests were resolved once the member learned the digital option existed and met their immediate need.'
WHERE dept_id = 10 AND title = 'ID Card Reissue SOP v3';

-- --- Address Change Verification Policy -----------------------------
UPDATE knowledge_docs SET content = 'An address change request must be verified before being applied to the member record: acceptable verification includes a successful identity check via the standard authentication questions, a written request with a signature matching one on file, or an in-person verification at a service center. Address changes affect where ID cards, EOBs, and other correspondence are sent, so an unverified change is a meaningful risk if the requester is not actually the member. A change requested during an active grievance or dispute (see Grievance Intake Procedure) receives additional scrutiny, since address changes have occasionally been used to intercept correspondence during a contested case.'
WHERE dept_id = 10 AND title = 'Address Change Verification Policy';

UPDATE knowledge_docs SET content = 'Revision 2 adds a confirmation-to-old-address requirement on top of the verification methods in v1: after any address change is applied, a confirmation notice is sent to BOTH the new address and the old address on file, so a member whose identity was compromised has a chance to notice and report an unauthorized change even if the fraudulent requester passed the standard verification. This revision also shortens the effective-date lag for the change itself to next business day (from the same-day-in-theory but often-delayed v1 process), to reduce the window where correspondence could go to the wrong address during transition.'
WHERE dept_id = 10 AND title = 'Address Change Verification Policy v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds an out-of-state or out-of-country address flag: an address change to a location outside the member''s current plan service area triggers a coverage-eligibility review rather than being applied automatically, since many plans have service-area restrictions that an address change could inadvertently violate. This revision also clarifies the additional-scrutiny handling from v1 for active-grievance cases: the address change is not blocked, only flagged for a supervisor review before the confirmation notices in v2 are sent, so a legitimate change isn''t indefinitely delayed by an unrelated grievance.'
WHERE dept_id = 10 AND title = 'Address Change Verification Policy v3';

-- --- Grievance Intake Procedure -----------------------------
UPDATE knowledge_docs SET content = 'A grievance is any expression of dissatisfaction about the plan, a provider, or a service experience that is not a request to change a specific coverage or claim determination (which follows the standard appeals process instead). Grievances are logged with a HIGH priority by default and require an initial response to the member within 2 business days acknowledging receipt, even if full resolution takes longer. Grievances alleging discrimination, harassment, or a safety concern are escalated to a supervisor immediately upon intake, not handled through the standard queue regardless of default priority assignment. Every grievance must be resolved (not just acknowledged) within 30 calendar days, with a written resolution notice sent to the member.'
WHERE dept_id = 10 AND title = 'Grievance Intake Procedure';

UPDATE knowledge_docs SET content = 'Revision 2 shortens the initial acknowledgment window in v1 from 2 business days to 1 business day, and adds an explicit distinction the original SOP left ambiguous: a grievance about a specific claim denial should be redirected to the standard claims appeals process (handled by Claims, not Member Services) rather than logged as a grievance here, since the two processes have different regulatory timelines and logging a claim dispute as a grievance was causing appeal-deadline confusion for members. This revision also adds a grievance trending report requirement: grievances are reviewed monthly in aggregate by category to identify systemic issues, not just resolved one at a time.'
WHERE dept_id = 10 AND title = 'Grievance Intake Procedure v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds an expedited grievance path for situations involving an immediate access-to-care concern (distinct from the safety/discrimination immediate-escalation in v1): if the grievance describes an ongoing barrier to receiving needed care right now, resolution must be attempted within 72 hours rather than the standard 30-day window. This revision also formalizes the claim-dispute redirect from v2 with a required warm handoff: the member must be told explicitly which process (grievance vs. appeal) applies and why, not simply redirected without explanation, since silent redirection was generating its own complaints.'
WHERE dept_id = 10 AND title = 'Grievance Intake Procedure v3';

-- --- Open Enrollment FAQ -----------------------------
UPDATE knowledge_docs SET content = 'Open enrollment is the annual period during which members may change plans, add or remove dependents, or newly enroll without a qualifying life event. Outside open enrollment, plan changes generally require a qualifying life event (marriage, birth/adoption, loss of other coverage, etc.) reported within 30 days of the event. Coverage elected during open enrollment takes effect at the start of the next plan year, not immediately. A member who does not actively make a change during open enrollment is generally auto-re-enrolled in their current plan, unless that plan is being discontinued, in which case the member is defaulted to the most comparable available plan and notified of the change.'
WHERE dept_id = 10 AND title = 'Open Enrollment FAQ';

UPDATE knowledge_docs SET content = 'Revision 2 extends the qualifying-life-event reporting window in v1 from 30 to 60 days, aligning with updated regulatory guidance, and adds explicit examples of what does NOT qualify as a life event (a simple preference change, a provider leaving the network) to reduce member confusion about when off-cycle changes are actually permitted. This revision also clarifies the auto-re-enrollment default in v1: if a member''s current plan increases premium significantly year-over-year, the auto-re-enrollment notice must prominently disclose the new premium, not just confirm continued enrollment.'
WHERE dept_id = 10 AND title = 'Open Enrollment FAQ v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a grace period for late qualifying-life-event reporting: a report submitted up to 15 days after the 60-day window in v2 may still be honored with supervisor approval if the delay was reasonably explained (e.g. the member was hospitalized), rather than an automatic hard denial at exactly 60 days. This revision also adds explicit guidance for the discontinued-plan default-enrollment scenario in v1: the comparable-plan determination must be documented with the specific factors compared (premium, network, deductible), so a member questioning the default assignment has a concrete basis to review, not just "most similar" as a conclusion.'
WHERE dept_id = 10 AND title = 'Open Enrollment FAQ v3';

-- --- Coverage Question Escalation Guide -----------------------------
UPDATE knowledge_docs SET content = 'Most coverage questions (is a specific service covered, what is my deductible status, is a specific provider in-network) can be answered directly from the member''s plan documents and current benefit accumulator data without escalation. Escalate to a benefits specialist when the question involves plan document interpretation ambiguity, a benefit that appears to have been applied incorrectly, or a coverage question tied to an active prior authorization or claim dispute. Escalated coverage questions should be resolved within 3 business days; if a definitive answer requires input from Claims or Prior Authorization, the member should be told which department is involved and a realistic timeline, not left with an open-ended "we are still looking into it."'
WHERE dept_id = 10 AND title = 'Coverage Question Escalation Guide';

UPDATE knowledge_docs SET content = 'Revision 2 adds a first-call-resolution target alongside the escalation criteria in v1: agents should attempt to resolve straightforward coverage questions using the self-service benefit lookup tool before escalating, since post-implementation review found questions escalated unnecessarily when the answer was actually available directly. This revision also shortens the escalated-question resolution window from 3 business days to 2 for questions tied to an active, time-sensitive prior authorization, since a slow coverage-question answer in that context can delay care.'
WHERE dept_id = 10 AND title = 'Coverage Question Escalation Guide v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a documented-source requirement to every escalated answer: a benefits specialist resolving an escalated question must cite the specific plan document section or benefit rule used, not just state the conclusion, so the member (and any subsequent agent handling a follow-up) can see the actual basis for the answer. This revision also formalizes the cross-department timeline communication from v1 into a required ticket field, so "waiting on Claims" or "waiting on Prior Auth" is tracked structurally rather than only mentioned to the member verbally.'
WHERE dept_id = 10 AND title = 'Coverage Question Escalation Guide v3';
